      backup_text =
        "# Night Garden Harvest Ledger #\n\
         # Track harvests and streak bonuses #\n\n\
         # Quality tiers from the moonlit fields #\n\
         type Quality =\n\
         + Bronze      # Common harvest, basic value #\n\
         + Silver      # Good quality, moderate bonus #\n\
         + Gold        # Excellent harvest, high value #\n\
         + Starlight   # Legendary, blessed by the moon #\n\
         in\n\n\
         # Crops that grow under the night sky #\n\
         type Crop =\n\
         + Moonmelon   # Glows faintly, sweet taste #\n\
         + Starfruit   # Shaped like stars, tangy #\n\
         + Nightshade  # Purple bloom, magical properties #\n\
         + Glowpumpkin # Orange and luminescent #\n\
         + Duskwheat   # Golden stalks, hearty grain #\n\
         in\n\n\
         # A single harvest from the garden #\n\
         type Harvest = (\n\
         crop = Crop,\n\
         quality = Quality,\n\
         quantity = Int\n\
         ) in\n\n\
         # The harvest ledger tracks all harvests and bonuses #\n\
         type Model = (\n\
         harvests = [Harvest],\n\
         totalValue = Int,\n\
         streakBonus = Int,\n\
         lastQuality = Quality\n\
         ) in\n\n\
         # Actions the farmer can take #\n\
         type Action =\n\
         + RecordHarvest(Harvest)  # Log a new harvest #\n\
         + ClaimBonus              # Collect accumulated streak bonus #\n\
         + CloseDay                # End the harvest day, reset streaks #\n\
         in\n\n\
         # Calculate base value of a crop #\n\
         let cropValue : Crop -> Int =\n\
         fun c ->\n\
         case c\n\
         | Moonmelon => 15\n\
         | Starfruit => 20\n\
         | Nightshade => 20\n\
         | Glowpumpkin => 12\n\
         | Duskwheat => 10\n\
         end\n\
         in\n\n\
         # Quality multiplier for harvest value #\n\
         let qualityMultiplier : Quality -> Int =\n\
         fun q ->\n\
         case q\n\
         | Bronze => 1\n\
         | Silver => 2\n\
         | Gold => 3\n\
         | Starlight => 5\n\
         end\n\
         in\n\n\
         # Calculate the value of a single harvest #\n\
         let harvestValue : Harvest -> Int =\n\
         fun h ->\n\
         cropValue(h.crop) * qualityMultiplier(h.quality) * h.quantity\n\
         in\n\n\
         # Initial empty ledger #\n\
         let initModel : Model = (\n\
         harvests = [],\n\
         totalValue = 0,\n\
         streakBonus = 0,\n\
         lastQuality = Bronze\n\
         ) in\n\n\
         # Process a harvest action and update the ledger #\n\
         let processHarvest : (Model, Harvest) -> Model =\n\
         fun (ledger, h) ->\n\
         let value = harvestValue(h) in\n\
         let isFirst = length(ledger.harvests) == 0 in\n\
         let newLast = h.quality in\n\
         let continues = !isFirst && h.quality == newLast in\n\
         let newStreak =\n\
         if continues\n\
         then ledger.streakBonus + 5\n\
         else 0\n\
         in\n\
         (\n\
         harvests = h :: ledger.harvests,\n\
         totalValue = ledger.totalValue + value + newStreak,\n\
         streakBonus = newStreak,\n\
         lastQuality = newLast\n\
         )\n\
         in\n\n\
         # Claim the streak bonus and reset it #\n\
         let claimBonus : Model -> Model =\n\
         fun ledger ->\n\
         (\n\
         harvests = ledger.harvests,\n\
         totalValue = ledger.totalValue + ledger.streakBonus,\n\
         streakBonus = 0,\n\
         lastQuality = ledger.lastQuality\n\
         )\n\
         in\n\n\
         # Close the harvest day - reset streak tracking #\n\
         let closeDay : Model -> Model =\n\
         fun ledger ->\n\
         (\n\
         harvests = ledger.harvests,\n\
         totalValue = ledger.totalValue,\n\
         streakBonus = 0,\n\
         lastQuality = Bronze\n\
         )\n\
         in\n\n\
         # Main update function - dispatch actions #\n\
         let update : (Model, Action) -> Model =\n\
         fun (ledger, action) ->\n\
         case action\n\
         | RecordHarvest(h) => processHarvest(ledger, h)\n\
         | ClaimBonus => claimBonus(ledger)\n\
         | CloseDay => closeDay(ledger)\n\
         end\n\
         in\n\n\
         # Run multiple actions in sequence #\n\
         let run : (Model, [Action]) -> Model =\n\
         fun (ledger, actions) ->\n\
         fold_left(actions, update, ledger)\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         # Basic harvest recording #\n\
         hint \"recording harvest adds to total value\"\n\
         test\n\
         let h = (crop = Moonmelon, quality = Bronze, quantity = 2) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.totalValue == 30\n\
         end;\n\n\
         hint \"harvest is added to harvests list\"\n\
         test\n\
         let h = (crop = Starfruit, quality = Silver, quantity = 1) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         length(ledger.harvests) == 1\n\
         end;\n\n\
         # Quality multiplier tests #\n\
         hint \"silver quality doubles value\"\n\
         test\n\
         let h = (crop = Duskwheat, quality = Silver, quantity = 1) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.totalValue == 20\n\
         end;\n\n\
         hint \"gold quality triples value\"\n\
         test\n\
         let h = (crop = Duskwheat, quality = Gold, quantity = 1) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.totalValue == 30\n\
         end;\n\n\
         hint \"starlight quality gives 5x value\"\n\
         test\n\
         let h = (crop = Nightshade, quality = Starlight, quantity = 1) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.totalValue == 100\n\
         end;\n\n\
         # Streak bonus tests #\n\
         hint \"same quality builds streak\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let ledger = run(initModel, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
         ledger.streakBonus == 5\n\
         end;\n\n\
         hint \"streak bonus accumulates with consecutive same-quality \
         harvests\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Silver, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Silver, quantity = 1) in\n\
         let h3 = (crop = Nightshade, quality = Silver, quantity = 1) in\n\
         let ledger = run(initModel, [\n\
         RecordHarvest(h1),\n\
         RecordHarvest(h2),\n\
         RecordHarvest(h3)\n\
         ]) in\n\
         ledger.streakBonus == 10\n\
         end;\n\n\
         hint \"different quality resets streak\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Bronze, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let ledger = run(initModel, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
         ledger.streakBonus == 0\n\
         end;\n\n\
         hint \"streak resets then can build again\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Bronze, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let h3 = (crop = Nightshade, quality = Gold, quantity = 1) in\n\
         let ledger = run(initModel, [\n\
         RecordHarvest(h1),\n\
         RecordHarvest(h2),\n\
         RecordHarvest(h3)\n\
         ]) in\n\
         ledger.streakBonus == 5\n\
         end;\n\n\
         # Claim bonus tests #\n\
         hint \"claiming bonus adds to total\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let ledger = run(initModel, [\n\
         RecordHarvest(h1),\n\
         RecordHarvest(h2),\n\
         ClaimBonus\n\
         ]) in\n\
         ledger.streakBonus == 0\n\
         end;\n\n\
         # Close day tests #\n\
         hint \"closing day resets streak tracking\"\n\
         test\n\
         let h1 = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
         let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let ledger = run(initModel, [\n\
         RecordHarvest(h1),\n\
         RecordHarvest(h2),\n\
         CloseDay\n\
         ]) in\n\
         ledger.streakBonus == 0 && ledger.lastQuality == Bronze\n\
         end;\n\n\
         # lastQuality tracking tests #\n\
         hint \"lastQuality tracks most recent harvest quality\"\n\
         test\n\
         let h = (crop = Moonmelon, quality = Starlight, quantity = 1) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.lastQuality == Starlight\n\
         end;\n\n\
         # Crop value tests #\n\
         hint \"starfruit/nightshade have highest base value\"\n\
         test\n\
         let h1 = (crop = Nightshade, quality = Bronze, quantity = 1) in\n\
         let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in\n\
         let ledger1 = update(initModel, RecordHarvest(h1)) in\n\
         let ledger2 = update(initModel, RecordHarvest(h2)) in\n\
         ledger1.totalValue > ledger2.totalValue\n\
         end;\n\n\
         hint \"duskwheat has lowest base value\"\n\
         test\n\
         let h1 = (crop = Duskwheat, quality = Bronze, quantity = 1) in\n\
         let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in\n\
         let ledger1 = update(initModel, RecordHarvest(h1)) in\n\
         let ledger2 = update(initModel, RecordHarvest(h2)) in\n\
         ledger1.totalValue < ledger2.totalValue\n\
         end;\n\n\
         # Quantity tests #\n\
         hint \"quantity multiplies value\"\n\
         test\n\
         let h = (crop = Moonmelon, quality = Bronze, quantity = 5) in\n\
         let ledger = update(initModel, RecordHarvest(h)) in\n\
         ledger.totalValue == 75\n\
         end;\n\n\
         # Complex scenario test #\n\
         hint \"full harvest day scenario\"\n\
         test\n\
         let ledger = run(initModel, [\n\
         RecordHarvest((crop = Duskwheat, quality = Bronze, quantity = 3)),\n\
         RecordHarvest((crop = Moonmelon, quality = Bronze, quantity = 2)),\n\
         RecordHarvest((crop = Starfruit, quality = Gold, quantity = 1)),\n\
         RecordHarvest((crop = Nightshade, quality = Gold, quantity = 1)),\n\
         ClaimBonus,\n\
         CloseDay\n\
         ]) in\n\
         ledger.streakBonus == 0 &&\n\
         length(ledger.harvests) == 4\n\
         end;\n\n\
         # Demo: A festival harvest day #\n\
         run(initModel, [\n\
         RecordHarvest((crop = Moonmelon, quality = Silver, quantity = 2)),\n\
         RecordHarvest((crop = Starfruit, quality = Silver, quantity = 1)),\n\
         RecordHarvest((crop = Nightshade, quality = Gold, quantity = 1)),\n\
         ClaimBonus\n\
         ])\n";
      refractors = "()";
    } )
